// ================================================
// ETAPA 1: VALIDAR CAMPOS E GERAR SLUG
// ================================================
const item = $input.item.json;

// Validação de campos obrigatórios
const required = ['keyword', 'title'];
for (const field of required) {
  if (!item[field] || String(item[field]).trim() === '') {
    throw new Error(`Campo obrigatório ausente: "${field}" | Linha: ${item.row_number || 'N/A'}`);
  }
}

// Gerador de slug SEO (remove acentos, lowercase, hífens)
function generateSlug(text) {
  return text
    .toString()
    .toLowerCase()
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')  // remove acentos
    .replace(/[^a-z0-9\s-]/g, '')    // só letras/números/espaços
    .trim()
    .replace(/\s+/g, '-')            // espaços → hífens
    .replace(/-+/g, '-')             // múltiplos hífens → um
    .substring(0, 60)                // máx 60 chars
    .replace(/-$/, '');              // remove hífen final
}

const slug = item.slug ? generateSlug(item.slug) : generateSlug(item.title);
const pubDate = new Date().toISOString().split('T')[0];
const timestamp = new Date().toISOString();

return {
  json: {
    ...item,
    slug,
    pubDate,
    timestamp,
    filename: `${slug}.md`,
    githubPath: `src/content/blog/${slug}.md`,
    rowNumber: item.row_number || item['row_number'] || '',
    author: item.author || 'SmartOps SEO',
  }
};

// ================================================
// ETAPA 2: MONTAR PAYLOAD COMPLETO PARA OPENAI
// ================================================
const d = $input.item.json;

const systemPrompt = `Você é um especialista em SEO técnico e copywriting com 10 anos de experiência criando conteúdo de alta performance para o Google.

RESPONDA SOMENTE COM UM OBJETO JSON VÁLIDO — sem markdown, sem texto antes ou depois do JSON.

ESTRUTURA OBRIGATÓRIA DA RESPOSTA:
{
  "title": "Título SEO otimizado entre 50 e 60 caracteres",
  "description": "Meta description persuasiva entre 150 e 160 caracteres com call-to-action implícito",
  "tags": ["tag1", "tag2", "tag3", "tag4", "tag5"],
  "heroImage": "",
  "content": "artigo completo em Markdown válido"
}

REGRAS OBRIGATÓRIAS PARA O CAMPO content:
1. Mínimo 1.500 palavras
2. Keyword density: 1-2% (uso natural, nunca forçado)
3. Português brasileiro formal mas acessível
4. H2 (##) e H3 (###) devem conter a keyword ou variações semânticas/LSI
5. FAQ obrigatório: 3-5 perguntas com H3, respondidas em 2-3 frases (melhora featured snippets)
6. CTA explícito na conclusão
7. Pelo menos 1 tabela comparativa ou de dados quando aplicável
8. Use **negrito** para termos-chave importantes
9. Parágrafos curtos (máx. 3-4 linhas) para melhor UX e SEO`;

const userPrompt = `Escreva um artigo SEO completo e profissional sobre: ${d.keyword}

DATOS DO ARTIGO:
- Título sugerido: ${d.title}
- Público-alvo: ${d.target_audience || 'empreendedores e profissionais de marketing digital'}
- Keyword principal: ${d.keyword}
- Contexto adicional: ${d.description_hint || 'Não informado'}

ESTRUTURA OBRIGATÓRIA DO CAMPO "content" (em Markdown):

## Introdução
Abra com a keyword principal nas primeiras 100 palavras.
Apresente o problema ou oportunidade central que o artigo resolve.
Termine com um gancho que motive o leitor a continuar.

## [H2: Benefícios e Fundamentos de ${d.keyword}]
3-4 parágrafos densos de valor.
Use uma lista bullet com os pontos principais.
Inclua pelo menos um dado estatístico ou estudo relevante.

## [H2: Como Implementar ${d.keyword} — Passo a Passo]
Lista numerada com etapas claras e acionáveis.
Cada etapa deve ter uma ação concreta.
Subtítulos H3 para cada fase principal se necessário.
Mini-case ou exemplo prático.

## [H2: Estratégias Avançadas e Erros a Evitar]
Táticas avançadas para resultados acima da média.
Tabela comparativa ou de dados (obrigatória aqui se aplicável).
Lista dos 3-5 erros mais comuns com ${d.keyword} e como evitá-los.

## Perguntas Frequentes sobre ${d.keyword}

### [Pergunta 1: dúvida mais comum sobre ${d.keyword}]?
Resposta direta em 2-3 frases. Responda de forma que possa aparecer em featured snippet.

### [Pergunta 2: sobre implementação prática]?
Resposta direta em 2-3 frases com dado ou exemplo.

### [Pergunta 3: sobre resultados ou ROI]?
Resposta direta em 2-3 frases com contexto temporal.

### [Pergunta 4: sobre erros ou limitações]?
Resposta direta em 2-3 frases.

## Conclusão
Resumo dos 3 pontos mais importantes.
CTA explícito: qual é o próximo passo concreto que o leitor deve tomar agora?
Reforce a transformação que o leitor terá ao aplicar o conteúdo.`;

return {
  json: {
    ...d,
    openaiBody: {
      model: 'gpt-4o',
      temperature: 0.7,
      max_tokens: 4096,
      response_format: { type: 'json_object' },
      messages: [
        { role: 'system', content: systemPrompt },
        { role: 'user', content: userPrompt }
      ]
    }
  }
};

// ================================================
// ETAPA 3: PARSEAR RESPOSTA OPENAI E MONTAR MARKDOWN
// ================================================
const openaiResp = $input.item.json;

// Recupera dados preparados na etapa 1
const prepared = $('⚙️ Code — Preparar Dados').item.json;

// Extrai conteúdo da resposta OpenAI
const rawContent = openaiResp?.choices?.[0]?.message?.content;
if (!rawContent) {
  throw new Error('OpenAI retornou resposta vazia ou inválida.');
}

// Parse JSON retornado pela OpenAI
let article;
try {
  article = JSON.parse(rawContent);
} catch (e) {
  throw new Error(`OpenAI não retornou JSON válido. Preview: ${rawContent.substring(0, 300)}`);
}

// Validação dos campos obrigatórios da resposta
if (!article.title) throw new Error('OpenAI: campo "title" ausente na resposta');
if (!article.description) throw new Error('OpenAI: campo "description" ausente na resposta');
if (!article.content) throw new Error('OpenAI: campo "content" ausente na resposta');

// Sanitiza strings para uso seguro no YAML frontmatter
function sanitizeYaml(str) {
  return String(str).replace(/"/g, "'").replace(/\n/g, ' ').trim();
}

// Normaliza tags
const tags = Array.isArray(article.tags) && article.tags.length > 0
  ? article.tags
  : [prepared.keyword];

// Monta o frontmatter YAML
const frontmatter = [
  '---',
  `title: "${sanitizeYaml(article.title)}"`,
  `description: "${sanitizeYaml(article.description)}"`,
  `pubDate: "${prepared.pubDate}"`,
  `author: "${sanitizeYaml(prepared.author)}"`,
  `tags: ${JSON.stringify(tags)}`,
  `heroImage: "${article.heroImage || ''}"`,
  '---',
].join('\n');

// Conteúdo final do arquivo .md
const markdownContent = frontmatter + '\n\n' + article.content.trim();

// Métricas de uso
const wordCount = article.content.split(/\s+/).length;
const inputTokens = openaiResp?.usage?.prompt_tokens || 0;
const outputTokens = openaiResp?.usage?.completion_tokens || 0;
const totalTokens = openaiResp?.usage?.total_tokens || 0;

return {
  json: {
    ...prepared,
    markdownContent,
    seoTitle: article.title,
    seoDescription: article.description,
    tags,
    heroImage: article.heroImage || '',
    wordCount,
    inputTokens,
    outputTokens,
    totalTokens,
  }
};

// ================================================
// ETAPA 4: CONVERTER MARKDOWN PARA BASE64
// (exigido pela GitHub Contents API)
// ================================================
const data = $input.item.json;

if (!data.markdownContent) {
  throw new Error('markdownContent ausente — etapa anterior falhou.');
}

const base64Content = Buffer.from(data.markdownContent, 'utf-8').toString('base64');

return {
  json: {
    ...data,
    base64Content,
    contentLength: data.markdownContent.length,
  }
};
